from html import unescape

def clean_text(text: str) -> str:
    if not text:
        return ""

    # HTML 엔티티 복원
    text = unescape(text)

    # HTML 태그 제거
    text = re.sub(r"<[^>]+>", " ", text)

    # 공백 정리
    text = re.sub(r"\s+", " ", text).strip()

    return text

